<template>
    <div>
        <Head title="Buttons" />

        <Card>
            <template #start>
                <div class="row">
                    <section class="md:col-6">
                        <div class="card-header">
                            <h4 class="card-title">Pick your Color</h4>
                        </div>
                        <div class="card-body d-flex flex-wrap align-items-center button-examples">
                            <button v-for="button in colors" :key="button.label" type="button" class="btn" :class="button.variant">
                                {{ button.label }}
                            </button>
                        </div>
                    </section>
                    <section class="md:col-6">
                        <div class="card-header">
                            <h4 class="card-title">Buttons with Label</h4>
                        </div>
                        <div class="card-body d-flex flex-wrap align-items-center button-examples">
                            <button v-for="button in labeledButtons" :key="button.label" type="button" class="btn" :class="button.variant">
                                <span v-if="button.position === 'start'" class="btn-label">
                                    <i class="material-icons" aria-hidden="true">{{ button.icon }}</i>
                                </span>
                                <i v-else-if="button.position === 'inline'" class="material-icons" aria-hidden="true">{{ button.icon }}</i>
                                {{ button.label }}
                                <span v-if="button.position === 'end'" class="btn-label btn-label-right">
                                    <i class="material-icons" aria-hidden="true">{{ button.icon }}</i>
                                </span>
                            </button>
                        </div>
                    </section>
                </div>

                <div class="row">
                    <section class="md:col-6">
                        <div class="card-header">
                            <h4 class="card-title">Pick your Size</h4>
                        </div>
                        <div class="card-body d-flex flex-wrap align-items-center button-examples">
                            <button type="button" class="btn btn-primary btn-sm">Small</button>
                            <button type="button" class="btn btn-primary">Regular</button>
                            <button type="button" class="btn btn-primary btn-lg">Large</button>
                        </div>
                    </section>
                    <section class="md:col-6">
                        <div class="card-header">
                            <h4 class="card-title">Pick your Style</h4>
                        </div>
                        <div class="card-body d-flex flex-wrap align-items-center button-examples">
                            <button type="button" class="btn btn-primary">Default</button>
                            <button type="button" class="btn btn-primary btn-round">Round</button>
                            <button type="button" class="btn btn-primary btn-round">
                                <i class="material-icons" aria-hidden="true">favorite</i> With icon
                            </button>
                            <button type="button" class="btn btn-primary btn-round btn-fab" aria-label="Favorite">
                                <i class="material-icons" aria-hidden="true">favorite</i>
                            </button>
                            <button type="button" class="btn btn-primary btn-link">Simple</button>
                        </div>
                    </section>
                </div>

                <div class="row">
                    <section class="md:col-6">
                        <div class="card-header">
                            <h4 class="card-title">Pagination</h4>
                        </div>
                        <div class="card-body">
                            <nav v-for="example in pagination" :key="example.label" :aria-label="example.label">
                                <ul class="pagination" :class="example.variant">
                                    <li v-if="example.arrows" class="page-item" :class="{ disabled: example.page === 1 }">
                                        <button type="button" class="page-link" aria-label="Previous page" :disabled="example.page === 1" @click="example.page--">
                                            <span aria-hidden="true">«</span>
                                        </button>
                                    </li>
                                    <li v-for="page in example.total" :key="page" class="page-item" :class="{ active: page === example.page }">
                                        <button type="button" class="page-link" :aria-current="page === example.page ? 'page' : undefined" @click="example.page = page">
                                            {{ page }}
                                        </button>
                                    </li>
                                    <li v-if="example.arrows" class="page-item" :class="{ disabled: example.page === example.total }">
                                        <button type="button" class="page-link" aria-label="Next page" :disabled="example.page === example.total" @click="example.page++">
                                            <span aria-hidden="true">»</span>
                                        </button>
                                    </li>
                                </ul>
                            </nav>
                        </div>
                    </section>
                    <section class="md:col-6">
                        <div class="card-header">
                            <h4 class="card-title">Button Group</h4>
                        </div>
                        <div class="card-body">
                            <div class="btn-group" role="group" aria-label="Button group example">
                                <button v-for="label in ['Left', 'Middle', 'Right']" :key="label" type="button" class="btn btn-info">{{ label }}</button>
                            </div>
                            <div class="d-flex flex-wrap gap-1 mt-4">
                                <div class="btn-group" role="group" aria-label="Toggle buttons">
                                    <button
                                        v-for="number in 4"
                                        :key="number"
                                        type="button"
                                        class="btn btn-round btn-info"
                                        :class="{ active: pressedButtons[number] }"
                                        :aria-pressed="Boolean(pressedButtons[number])"
                                        @click="pressedButtons[number] = !pressedButtons[number]"
                                    >
                                        {{ number }}
                                    </button>
                                </div>
                                <div class="btn-group" role="group" aria-label="Number buttons">
                                    <button v-for="number in [5, 6, 7]" :key="number" type="button" class="btn btn-round btn-info">{{ number }}</button>
                                </div>
                            </div>
                        </div>
                    </section>
                </div>

                <section>
                    <div class="card-header">
                        <h4 class="card-title">Social buttons</h4>
                    </div>
                    <div class="card-body social-buttons">
                        <div class="social-button-row social-button-headings">
                            <span>Default</span>
                            <span>Neutral</span>
                        </div>
                        <div v-for="network in socialButtons" :key="network.id" class="social-button-row" role="group" :aria-label="network.name">
                            <button
                                v-for="style in socialStyles"
                                :key="style.name"
                                type="button"
                                class="btn"
                                :class="[`btn-${network.id}`, style.classes]"
                                :aria-label="style.iconOnly ? `${network.name}, ${style.name}` : undefined"
                            >
                                <i class="fa" aria-hidden="true">{{ style.iconOnly ? network.icon : network.labelIcon ?? network.icon }}</i>
                                <template v-if="!style.iconOnly">{{ ' ' + network.label }}</template>
                            </button>
                        </div>
                    </div>
                </section>
            </template>
        </Card>
    </div>
</template>

<script>
import { Head } from '@inertiajs/vue3';
import Card from '@scaffold/components/Card.vue';

export default {
    name: 'ButtonsDemo',
    components: { Card, Head },
    layout: { pageTitle: 'Buttons' },
    data() {
        return {
            colors: [
                { label: 'Default' },
                { label: 'Primary', variant: 'btn-primary' },
                { label: 'Info', variant: 'btn-info' },
                { label: 'Success', variant: 'btn-success' },
                { label: 'Warning', variant: 'btn-warning' },
                { label: 'Danger', variant: 'btn-danger' },
            ],
            labeledButtons: [
                { label: 'Left', icon: 'keyboard_arrow_left', position: 'start' },
                { label: 'Right', icon: 'keyboard_arrow_right', position: 'end' },
                { label: 'Info', icon: 'priority_high', variant: 'btn-info', position: 'start' },
                { label: 'Success', icon: 'check', variant: 'btn-success', position: 'start' },
                { label: 'Warning', icon: 'warning', variant: 'btn-warning', position: 'inline' },
                { label: 'Danger', icon: 'close', variant: 'btn-danger', position: 'inline' },
            ],
            pagination: [
                { label: 'Primary pagination example', variant: 'pagination-primary', total: 5, page: 1 },
                { label: 'Pagination example with arrows', arrows: true, total: 3, page: 2 },
            ],
            pressedButtons: {},
            socialStyles: [
                { name: 'Default' },
                { name: 'Square icon', classes: 'btn-just-icon', iconOnly: true },
                { name: 'Round icon', classes: 'btn-just-icon btn-round', iconOnly: true },
                { name: 'Neutral icon', classes: 'btn-just-icon btn-link', iconOnly: true },
                { name: 'Neutral text', classes: 'btn-link' },
            ],
            socialButtons: [
                { id: 'twitter', name: 'Twitter', icon: '\uf099', label: 'Connect with Twitter' },
                { id: 'facebook', name: 'Facebook', icon: '\uf09a', labelIcon: '\uf082', label: 'Share · 2.2k' },
                { id: 'google', name: 'Google+', icon: '\uf0d5', label: 'Share on Google+' },
                { id: 'linkedin', name: 'LinkedIn', icon: '\uf0e1', labelIcon: '\uf08c', label: 'Connect with LinkedIn' },
                { id: 'pinterest', name: 'Pinterest', icon: '\uf0d2', label: 'Pin it · 212' },
                { id: 'youtube', name: 'YouTube', icon: '\uf167', labelIcon: '\uf16a', label: 'View on YouTube' },
                { id: 'tumblr', name: 'Tumblr', icon: '\uf173', labelIcon: '\uf174', label: 'Repost' },
                { id: 'github', name: 'GitHub', icon: '\uf09b', label: 'Connect with GitHub' },
                { id: 'behance', name: 'Behance', icon: '\uf1b4', labelIcon: '\uf1b5', label: 'Follow us' },
                { id: 'dribbble', name: 'Dribbble', icon: '\uf17d', label: 'Find us on Dribbble' },
                { id: 'reddit', name: 'Reddit', icon: '\uf1a1', label: 'Repost · 232' },
            ],
        };
    },
};
</script>

<style scoped>
.button-examples {
    column-gap: .1875rem;
}

.social-buttons {
    container-type: inline-size;
}

.social-button-row {
    display: grid;
    grid-template-columns: minmax(0, 4fr) repeat(3, minmax(2.75rem, 1fr)) minmax(0, 5fr);
    align-items: center;
    justify-items: start;
}

.social-button-headings {
    margin-bottom: 1rem;
}

.social-button-headings > :last-child {
    grid-column: 4;
}

@container (max-width: 42rem) {
    .social-button-row {
        display: flex;
        flex-wrap: wrap;
        column-gap: .25rem;
    }

    .social-button-headings {
        display: none;
    }
}
</style>
